// План specs/modals.md, 1.3 (кейс MD-03). Admin. Только чтение: текст не вводится, работа не создаётся, окно закрывается Esc. @prod-safe
import { test } from '@playwright/test';
import { ADMIN_STATE, DEVICES, closeWithEsc, expectOpaqueModalOverDimmedPage } from './modal-helpers';

test.use({ storageState: ADMIN_STATE });

test.describe('Модальные окна — непрозрачный фон (#08737d6c)', () => {
  for (const device of DEVICES) {
    test(`Create Job with AI window is opaque over a dimmed page #08737d6c ${device} @prod-safe`, async ({ page }) => {
      // Шаг 1: форма новой работы → Create with AI
      await page.goto('/JobForm?action=new');
      await page.getByRole('button', { name: 'Create with AI' }).filter({ visible: true }).first().click();

      // Шаг 2: окно непрозрачное, страница затемнена (заголовок окна не фиксируем — берём единственное открытое окно)
      const dialog = page.getByRole('dialog');
      await expectOpaqueModalOverDimmedPage(page, dialog);

      // Шаг 3: Esc
      await closeWithEsc(page, dialog);
    });
  }
});
